def preorder_recursive(root):
    if root is None:
        return
    visit(root)                     # 先访问根结点
    preorder_recursive(root.left)   # 再遍历左子树
    preorder_recursive(root.right)  # 最后遍历右子树


def preorder_iterative(root):
    if root is None:
        return
    stack = [root]
    while stack:
        node = stack.pop()          # 栈顶为当前子树的根
        visit(node)
        # 右子树先入栈，左子树后入栈，从而左子树先被弹出处理
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
